import{TaskType as e}from"../../../../types/common.js";const a={[e.EVENT]:"EVENT is a task used to publish an event into one of the supported eventing systems in Conductor.",[e.HTTP]:"HTTP task allows you to make calls to remote services exposed over HTTP/HTTPS.",[e.HTTP_POLL]:"The HTTP_POLL is a conductor task used to invoke HTTP API until the specified condition matches.",[e.JSON_JQ_TRANSFORM]:"The JSON_JQ_TRANSFORM task is a System task that allows the processing of JSON data that is supplied to the task by using the popular JQ processing tool’s query expression language.",[e.INLINE]:"The inline task helps execute necessary logic at the workflow run-time using an evaluator. The two supported evaluator types are javascript and graaljs.",[e.BUSINESS_RULE]:"Business rule task helps evaluate business rules compiled in spreadsheets.",[e.SENDGRID]:"Send email using sendgrid",[e.START_WORKFLOW]:"Start Workflow is an operator task used to start another workflow from an existing workflow. Unlike a sub-workflow task, a start workflow task doesn’t create a relationship between the current workflow and the newly started workflow. That means it doesn’t wait for the started workflow to get completed.",[e.WAIT_FOR_WEBHOOK]:"Webhook is an HTTP-based callback function that facilitates the communication between the Conductor and other third-party systems. It can be used to receive data from other applications to the Conductor.",[e.UPDATE_SECRET]:"A system task to update the value of any secret, given the user has permission to update the secret.",[e.QUERY_PROCESSOR]:"A system task for executing queries across different systems, tailored for purposes like alert generation.",[e.UPDATE_TASK]:"A system task to update the status of other tasks.",[e.SWITCH]:"The switch task is used for creating branching logic. It is a representation of multiple if...then...else or switch...case statements in programming.",[e.DO_WHILE]:"The Do While task sequentially executes a list of tasks as long as a condition is true. The list of tasks is executed first before the condition is checked, even for the first iteration, just like a regular do .. while task in programming languages.",[e.FORK_JOIN_DYNAMIC]:"A Fork/Join task can be used when you need to run tasks in parallel. It contains two components, the fork, and the join part. A fork operation lets you run a specified list of tasks in parallel. A fork task is followed by a join operation that waits on the forked tasks to finish. The JOIN task also collects outputs from each of the forked tasks.",[e.DYNAMIC]:"The dynamic task allows us to execute one of the registered tasks dynamically at run-time. This means that you can run a task not fixed at the time of the workflow’s execution. The task name could even be supplied as part of the workflow’s input and be mapped to the dynamic task input.",[e.TERMINATE]:"The Terminate task is a task that can terminate the current workflow with a termination status and reason.",[e.SET_VARIABLE]:"Set Variable allows us to set the workflow variables by creating or updating them with new values. Think of these as a temporary state, which you can set in any step and refer back to any steps that execute after setting the value.",[e.SUB_WORKFLOW]:"Sub Workflow allows executing another workflow from within the current workflow.",[e.JOIN]:"A JOIN task is used in conjunction with a FORK_JOIN or FORK_JOIN_DYNAMIC task to join all the tasks within the forks.",[e.WAIT]:"The Wait task is used when the workflow needs to be paused for an external signal to continue. It is used when the workflow needs to wait and pause for external signals, such as a human intervention (like manual approval) or an event coming from an external source, such as Kafka or SQS.",[e.TERMINATE_WORKFLOW]:"The Terminate Workflow task is used to terminate other workflows using their workflow IDs.",[e.HUMAN]:"Human tasks are used when you need to wait your workflow for an interaction with a human. When your workflow reaches the human task, it waits for a manual interaction to proceed with the workflow. It can be leveraged when you need manual approval from a human, such as when a form needs to be approved within an application, such as approval workflows.",[e.GET_WORKFLOW]:"Get Workflow task is used to retrieve detail of workflow using workflow ID.",[e.JDBC]:"A JDBC task is a system task used to execute or store information in MySQL.",[e.SIMPLE]:"A Simple task is a Worker task that requires an external worker for polling. The Workers can be implemented in any language, and Conductor SDKs provide additional features such as metrics, server communication, and polling threads that make the worker creation process easier.",[e.OPS_GENIE]:"A system task to send alerts to Opsgenie in the event of workflow failures. This task can be used in conjunction with the Query Processor task, which fetches metadata details to trigger alerts to Opsgenie as required.",[e.LLM_TEXT_COMPLETE]:"A system task to predict or generate the next phrase or words in a given text based on the context provided.",[e.LLM_GENERATE_EMBEDDINGS]:"A system task to generate embeddings from the input data provided. Embeddings are the processed input text converted into a sequence of vectors, which can then be stored in a vector database for retrieval later. You can use a model that was previously integrated to generate these embeddings.",[e.LLM_GET_EMBEDDINGS]:"A system task to get the numerical vector representations of words, phrases, sentences, or documents that have been previously learned or generated by the model. Unlike the process of generating embeddings (LLM Generate Embeddings task), which involves creating vector representations from input data, this task deals with the retrieval of pre-existing embeddings and uses them to search for data in vector databases.",[e.LLM_STORE_EMBEDDINGS]:"A system task responsible for storing the generated embeddings produced by the LLM Generate Embeddings task, into a vector database. The stored embeddings serve as a repository of information that can be later accessed by the LLM Get Embeddings task for efficient and quick retrieval of related data.",[e.LLM_SEARCH_INDEX]:"A system task to search the vector database or repository of vector embeddings of already processed and indexed documents to get the closest match. You can input a query that typically refers to a question, statement, or request made in natural language that is used to search, retrieve, or manipulate data stored in a database.",[e.LLM_INDEX_DOCUMENT]:"A system task to index the provided document into a vector database that can be efficiently searched, retrieved, and processed later.",[e.GET_DOCUMENT]:"A system task to retrieve the content of the document provided and use it for further data processing using AI tasks.",[e.LLM_INDEX_TEXT]:"A system task to index the provided text into a vector space that can be efficiently searched, retrieved, and processed later.",[e.LLM_CHAT_COMPLETE]:"A system task to complete the chat query. It can be used to instruct the model's behavior accurately to prevent any deviation from the objective.",[e.AGENT]:"Runs an agent to completion — a remote A2A (Agent2Agent) agent, or a registered agent on the embedded Conductor runtime. Supports poll, streaming (SSE), and push modes with durable retry and resumption.",[e.GET_AGENT_CARD]:"Fetches a remote A2A agent's Agent Card to discover its skills and capabilities at runtime.",[e.CANCEL_AGENT]:"Cancels a running task on a remote A2A agent (A2A tasks/cancel), or terminates a registered Conductor agent execution.",[e.LLM_SEARCH_EMBEDDINGS]:"Searches a vector database for the closest matches using a set of pre-computed embeddings, rather than generating embeddings from a query string.",[e.LIST_MCP_TOOLS]:"Lists the tools advertised by a Model Context Protocol (MCP) server so they can be used by agents and downstream tasks.",[e.CALL_MCP_TOOL]:"Invokes a named tool on a Model Context Protocol (MCP) server with the provided arguments and returns its result.",[e.GENERATE_IMAGE]:"Generates one or more images from a text prompt using an integrated LLM image-generation model.",[e.GENERATE_AUDIO]:"Synthesizes speech or audio from text using an integrated LLM audio model.",[e.GENERATE_VIDEO]:"Generates video from a text prompt or input image using an integrated LLM video model. Runs asynchronously, polling for completion.",[e.GENERATE_PDF]:"Converts markdown content into a styled PDF document with configurable page size, margins, and theme."};export{a as taskDescriptions};
//# sourceMappingURL=taskDescription.js.map
